begin;
create temp table profile_qa as select gen_random_uuid() as school,gen_random_uuid() as admin_id,gen_random_uuid() as admin_auth,gen_random_uuid() as teacher_id,gen_random_uuid() as teacher_auth,gen_random_uuid() as parent_auth,gen_random_uuid() as guardian,gen_random_uuid() as student;
grant select on profile_qa to authenticated;
insert into institutions(id,name,status) select school,'Isolated profile QA','trial' from profile_qa;
insert into school_users(id,institution_id,email,role,status,auth_user_id) select admin_id,school,'qa-admin@example.invalid','school_admin','active',admin_auth from profile_qa union all select teacher_id,school,'qa-teacher@example.invalid','teacher','active',teacher_auth from profile_qa;
insert into school_students(id,institution_id,admission_number,name,status) select student,school,'QA-PROFILE-ONLY','Isolated QA Student','active' from profile_qa;
insert into school_student_profiles(student_id,institution_id,admission_login_alias) select student,school,'KEEP-LOGIN-ALIAS' from profile_qa;
insert into auth.users(id,email,raw_app_meta_data) select parent_auth,'qa-parent-'||parent_auth::text||'@example.invalid','{}'::jsonb from profile_qa;
insert into school_guardians(id,institution_id,auth_user_id,email,status) select guardian,school,parent_auth,'qa-parent@example.invalid','active' from profile_qa;
insert into school_guardian_students(guardian_id,institution_id,student_id,relationship) select guardian,school,student,'guardian' from profile_qa;
select set_config('request.jwt.claims',jsonb_build_object('sub',admin_auth,'role','authenticated')::text,true) from profile_qa;
set local role authenticated;
select public.school_save_student_profile(student,'2015-03-12','{"guardian_name":"QA Guardian","guardian_relationship":"father","guardian_phone":"9000000013","city":"QA City","details":{"gender":"Male","blood_group":"O+","pen_number":"TEST-PEN-ONLY","father_name":"QA Father"}}'::jsonb) from profile_qa;
do $$ declare alias text; begin select admission_login_alias into alias from public.school_student_profiles where student_id=(select student from profile_qa); if alias<>'KEEP-LOGIN-ALIAS' then raise exception 'Save changed login alias'; end if; end $$;
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',parent_auth,'role','authenticated')::text,true) from profile_qa;
set local role authenticated;
do $$ declare n integer; begin select count(*) into n from public.school_student_profiles where student_id=(select student from profile_qa) and details->>'blood_group'='O+'; if n<>1 then raise exception 'Parent cannot read own expanded profile'; end if; update public.school_student_profiles set city='Unauthorized' where student_id=(select student from profile_qa); get diagnostics n=row_count; if n<>0 then raise exception 'Parent profile write accepted'; end if; begin perform public.school_save_student_profile(student,'2015-03-12','{}'::jsonb) from profile_qa; raise exception 'Parent profile RPC write accepted'; exception when insufficient_privilege then null; end; end $$;
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',teacher_auth,'role','authenticated')::text,true) from profile_qa;
set local role authenticated;
select jsonb_build_object('teacher_private_profile_rows',(select count(*) from public.school_student_profiles where institution_id=(select school from profile_qa)),'admin_save_parent_read_parent_write_denial_and_login_alias_preservation','passed') as verification;
rollback;
